    decoded.includes("\\") ||
    decoded.includes("//") ||
    decoded.includes("?") ||
    decoded.includes("#") ||
    decoded.includes("@") ||
    /[\u0000-\u001f\u007f]/.test(decoded) ||
    /(^|\/)\.{1,2}(\/|$)/.test(decoded) ||
    /(^|\/)[a-z][a-z0-9+.-]*:/i.test(decoded)
