   550	      if (relative === 'overview' && getOrHead) { await this.authorizeShell('overview', state); return this.headAware(request, success(await this.overviewView(state), identity.requestId)); }
   551	      if (relative === 'openapi.json' && getOrHead) { await this.authorizeShell('api', state); return this.headAware(request, response(this.openApi, 200, { 'x-request-id': identity.requestId })); }
   552	      if (relative === 'mcp' && getOrHead) { await this.authorizeShell('mcp', state); return this.headAware(request, success(this.mcpView(state), identity.requestId)); }
   553	      if (relative === 'search' && getOrHead) return this.headAware(request, success(await this.search(request, state), identity.requestId));
   554	      if (relative === 'audit' && getOrHead) return this.headAware(request, success(await this.audit(request, state), identity.requestId));
