   580	  private optionsResponse(relative: string, requestId: string): Response {
   581	    const methods = relative === 'mcp/transport'
   582	      ? ['GET', 'POST', 'DELETE', 'OPTIONS']
   583	      : relative === 'auth/sign-in' || relative === 'auth/2fa' || relative === 'auth/sign-out' || relative === 'confirmations' || relative.startsWith('operations/')
   584	      ? ['POST', 'OPTIONS']
   585	      : relative.startsWith('settings/policies/')
   586	        ? ['PATCH', 'OPTIONS']
   587	        : relative.startsWith('modules/')
   588	          ? ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS']
   589	          : this.isKnownEndpoint(relative)
   590	            ? ['GET', 'HEAD', 'OPTIONS']
   591	            : undefined;
   592	    if (!methods) throw new SuperConsoleHttpError('No administration endpoint exists at this path.', { status: 404, code: 'ADMIN_ROUTE_NOT_FOUND' });
