   596	  private relativePath(pathname: string): string {
   597	    const prefix = this.registry.apiBasePath;
   598	    if (pathname !== prefix && !pathname.startsWith(`${prefix}/`)) throw new SuperConsoleHttpError('The request is outside the administration API.', { status: 404, code: 'ADMIN_ROUTE_NOT_FOUND' });
   599	    const suffix = pathname.slice(prefix.length);
   600	    if (suffix.includes('\\') || suffix.includes('//')) {
   601	      throw new SuperConsoleHttpError('The administration path is not canonical.', { status: 400, code: 'INVALID_ADMIN_PATH' });
   602	    }
   603	    const rawSegments = suffix.replace(/^\/+|\/+$/g, '').split('/').filter(Boolean);
   604	    const decodedSegments = rawSegments.map((segment) => {
   605	      let decoded = segment;
   606	      for (let depth = 0; depth < 4; depth += 1) {
   607	        let next: string;
   608	        try {
   609	          next = decodeURIComponent(decoded);
   610	        } catch {
   611	          throw new SuperConsoleHttpError('The administration path contains invalid percent encoding.', { status: 400, code: 'INVALID_ADMIN_PATH' });
   612	        }
   613	        if (next === '.' || next === '..' || /[\/\\\u0000-\u001f\u007f]/.test(next)) {
   614	          throw new SuperConsoleHttpError('The administration path contains an unsafe segment.', { status: 400, code: 'INVALID_ADMIN_PATH' });
   615	        }
   616	        if (next === decoded) return segment;
   617	        decoded = next;
   618	      }
   619	      if (/%[0-9a-f]{2}/i.test(decoded)) {
   620	        throw new SuperConsoleHttpError('The administration path contains unstable nested encoding.', { status: 400, code: 'INVALID_ADMIN_PATH' });
   621	      }
   622	      return segment;
   623	    });
   624	    return decodedSegments.join('/');
   625	  }
